	/**
	 * Converts the soap model instances into normal model instances.
	 *
	 * @param soapModels the soap model instances to convert
	 * @return the normal model instances
	 */
	public static List<CandidateForm> toModels(CandidateFormSoap[] soapModels) {
		if (soapModels == null) {
			return null;
		}

		List<CandidateForm> models = new ArrayList<CandidateForm>(soapModels.length);

		for (CandidateFormSoap soapModel : soapModels) {
			models.add(toModel(soapModel));
		}

		return models;
	}

